* @param GesamtPlan $gesamtPlan Jahr des zugehörigen Gesamtplans
     * @param bool $nurAktiveDienstellen nur Fachpläne von aktiven akzeptieren? (auch Einfluss auf Fehlermeldung)
     * @return string "OK" oder lesbare Fehlermeldung für die Ausgabe
     */
    public static function addFachPlanung(
        string $nummer,
        GesamtPlan $gesamtPlan,
        bool $nurAktiveDienstellen = true
    ): string {
        Page::db()->beginTransaction();

        /** @var ?DienstStelle $dienstStelle */
        $dienstStelle = DienstStelle::getDienstStelle($nummer);
        if ($dienstStelle === null) {
            Page::db()->rollBack();
            return "Erstellen einer neuen Fachplanung fehlgeschlagen. Die Dienststelle <strong>$nummer</strong> wurde nicht gefunden! ";
        } elseif (!$dienstStelle->aktiv and $nurAktiveDienstellen) {
            Page::db()->rollBack();
            return "Erstellen einer neuen Fachplanung fehlgeschlagen. Die Dienststelle <strong>$nummer $dienstStelle->name</strong> wurde deaktiviert.";
        }

        $sql = "INSERT INTO fachplanung
                (fk_gesamtplan, fk_dienststelle, redakteur_level, geschlossen, name_dienststelle_historisch)
                VALUES (:jahr, :nummer, :level, :geschlossen, :name)";

        $statement = Page::db()->prepare($sql);
        $statement->bindValue(':jahr', $gesamtPlan->jahr, \PDO::PARAM_INT);
        $statement->bindValue(':nummer', $dienstStelle->nummer);
        $statement->bindValue(':level', $dienstStelle->isRessort() ? 4 : 2, \PDO::PARAM_INT);
        $statement->bindValue(':geschlossen', 0, \PDO::PARAM_INT);
        $statement->bindValue(':name', $dienstStelle->name);

        $errorMessageStart = "Die Fachplanung für die Dienststelle $dienstStelle->nummer $dienstStelle->name konnte nicht angelegt werden. ";

        if ($statement->execute()) {
            $vorherigerGesamtPlan = GesamtPlan::getVorherigerGesamtPlan($gesamtPlan);
            if ($vorherigerGesamtPlan === null) {
                Page::db()->commit();
                return "OK";
            }

            $resultMessage = self::copyMassnahmen($dienstStelle, $gesamtPlan, $vorherigerGesamtPlan);
            if ($resultMessage === "OK") {
                //Page::db()->rollBack();
                Page::db()->commit();
            } else {
                $resultMessage = $errorMessageStart . $resultMessage;
                Page::db()->rollBack();
            }
            return $resultMessage;
        } else {
            $errInfo = $statement->errorInfo();
            Page::db()->rollBack();
            if ($errInfo[1] === 1062) {
                return $errorMessageStart
                    . "Es existiert bereit eine Fachplanung für diese Dienststelle im IT-Gesamtplan "
                    . $gesamtPlan->getJahreText();
            }
            //return "DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n";
            return $errorMessageStart . 'Es ist ein Datenbank-Fehler aufgetreten (1).';
        }
    }

    /**
     * Kopiert Maßnahme aus der IT-Fachplanung des vorherigen IT-Gesamtplans in die neue
     * @param DienstStelle $dienstStelle Dienststelle der zu kopierenden IT-Fachplanung
     * @param GesamtPlan $gesamtPlan Gesamtplan
     * @param GesamtPlan $vorherigerGesamtPlan vorheriger Gesamtplan
     * @return string "OK" oder Fehlermeldung
     */
    protected static function copyMassnahmen(
        DienstStelle $dienstStelle,
        GesamtPlan $gesamtPlan,
        GesamtPlan $vorherigerGesamtPlan
    ): string {
        $newRedakteurLevel = $dienstStelle->parentRessort === null ? MemberShip::ACCESS_LEVEL_R2 : MemberShip::ACCESS_LEVEL_R3;

        /* Basis Datenfelder massnahme */
        // deleted, valid, etc. werden nicht übernommen, sondern auf default gesetzt.
        $insertFields = 'Ident,lft_nummer,fk_gesamtplan,fk_dienststelle,status_markiert,redakteur_level,fk_kopie_von,full_text,';
        $selectFields = "Ident,lft_nummer,{$gesamtPlan->jahr},fk_dienststelle,'kopiert',$newRedakteurLevel,id,full_text,";
        /* Weiter dynamische Felder */
        $moreFields = implode(', ', self::getFormFieldSqlNames($gesamtPlan->jahr, 'massnahme'));
        // dd($moreFields);
        $insertFields .= $moreFields;
        $selectFields .= $moreFields;

        $sql = "INSERT INTO massnahme ($insertFields)\n"
            . "SELECT $selectFields\n"
            . "FROM massnahme WHERE deleted = 0 AND aenderungs_antrag = 0\n"
            . "AND fk_gesamtplan={$vorherigerGesamtPlan->jahr} and fk_dienststelle='{$dienstStelle->nummer}'";
